import React, { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, ImageBackground, Dimensions } from 'react-native';
import backgroundImage from './assets/bgimage3.png'; // Import your background image

const { width, height } = Dimensions.get('window');

const App = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSignUp = () => {
    console.log('Email:', email);
    console.log('Password:', password);
  };

  const responsiveStyles = StyleSheet.create({
    formContainer: {
      backgroundColor: 'rgba(255, 255, 255, 0.7)',
      padding: 20,
      borderRadius: 10,
      width: width > 500 ? '60%' : '80%', // Responsive width
    },
    input: {
      height: 40,
      borderWidth: 1,
      borderRadius: 5,
      paddingHorizontal: 10,
      marginBottom: 10,
      fontSize: width > 500 ? 16 : 14, // Responsive font size
    },
    signUpButton: {
      backgroundColor: '#007AFF',
      paddingVertical: 10,
      borderRadius: 5,
      marginVertical: 5,
      height: 45, // Larger touch area
    },
  });

  return (
    <View style={styles.container}>
      <ImageBackground source={backgroundImage} style={styles.backgroundImage}>
        <View style={styles.contentContainer}>
          <View style={[styles.formContainer, responsiveStyles.formContainer]}>
            <Text style={styles.title}>Allowance Calculator</Text>
            <TextInput
              style={[styles.input, responsiveStyles.input]}
              placeholder="Email"
              value={email}
              onChangeText={setEmail}
              autoCapitalize="none"
              keyboardType="email-address"
            />
            <TextInput
              style={[styles.input, responsiveStyles.input]}
              placeholder="Password"
              value={password}
              onChangeText={setPassword}
              secureTextEntry
            />
            <TouchableOpacity style={[styles.signUpButton, responsiveStyles.signUpButton]} onPress={handleSignUp}>
              <Text style={styles.signUpButtonText}>Sign In</Text>
            </TouchableOpacity>
            <TouchableOpacity style={[styles.signUpButton, responsiveStyles.signUpButton]} onPress={handleSignUp}>
              <Text style={styles.signUpButtonText}>Continue With Google</Text>
            </TouchableOpacity>
            <Text style={styles.loginLink}>Error message here</Text>
          </View>
        </View>
      </ImageBackground>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  backgroundImage: {
    flex: 1,
    resizeMode: 'cover',
    justifyContent: 'center',
  },
  contentContainer: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-around',
    paddingHorizontal: 20,
  },
  formContainer: {
    backgroundColor: 'rgba(255, 255, 255, 0.7)',
    padding: 20,
    borderRadius: 10,
  },
  title: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 20,
    textAlign: 'center',
  },
  input: {
    height: 35,
    borderWidth: 1,
    borderRadius: 5,
    paddingHorizontal: 10,
    marginBottom: 10,
  },
  signUpButton: {
    backgroundColor: '#007AFF',
    paddingVertical: 10,
    borderRadius: 5,
    marginVertical: 5,
    height: 35,
  },
  signUpButtonText: {
    color: '#fff',
    fontWeight: 'bold',
    textAlign: 'center',
  },
  loginLink: {
    color: '#999',
    textAlign: 'center',
  },
});

export default App;
